from models import upgrade
import storage

def test_upgrade_v1_to_v2():
    v1 = {"id": 1, "name": "Task 1", "remote": "yes"}
    v2 = upgrade(v1)
    assert v2 == {"id": 1, "title": "Task 1", "work_mode": "remote", "version": 2}
    assert v1 == {"id": 1, "name": "Task 1", "remote": "yes"} # Original not modified

def test_upgrade_v1_no_remote():
    v1 = {"id": 2, "name": "Task 2"}
    v2 = upgrade(v1)
    assert v2 == {"id": 2, "title": "Task 2", "work_mode": "unknown", "version": 2}

def test_upgrade_v1_no_remote_none():
    v1 = {"id": 3, "name": "Task 3", "remote": None}
    v2 = upgrade(v1)
    assert v2 == {"id": 3, "title": "Task 3", "work_mode": "unknown", "version": 2}

def test_upgrade_v1_remote_no():
    v1 = {"id": 4, "name": "Task 4", "remote": "no"}
    v2 = upgrade(v1)
    assert v2 == {"id": 4, "title": "Task 4", "work_mode": "office", "version": 2}

def test_upgrade_v1_invalid_remote():
    v1 = {"id": 5, "name": "Task 5", "remote": "maybe"}
    try:
        upgrade(v1)
    except ValueError:
        pass
    else:
        assert False, "Should have raised ValueError for invalid remote"

def test_upgrade_v2_idempotent():
    v2 = {"version": 2, "id": 6, "title": "Task 6", "work_mode": "remote"}
    v2_copy = upgrade(v2)
    assert v2_copy == v2
    assert v2_copy is not v2 # Should be a copy

def test_storage_load_all():
    rows = [
        {"id": 1, "name": "T1", "remote": "yes"},
        {"version": 2, "id": 2, "title": "T2", "work_mode": "office"}
    ]
    results = storage.load_all(rows)
    assert len(results) == 2
    assert results[0] == {"id": 1, "title": "T1", "work_mode": "remote", "version": 2}
    assert results[1] == {"version": 2, "id": 2, "title": "T2", "work_mode": "office"}

def test_storage_save():
    v1 = {"id": 1, "name": "T1", "remote": "yes"}
    res1 = storage.save(v1)
    assert res1 == {"id": 1, "title": "T1", "work_mode": "remote", "version": 2}

    v2 = {"version": 2, "id": 2, "title": "T2", "work_mode": "office"}
    res2 = storage.save(v2)
    assert res2 == v2
    assert res2 is not v2

